styles:
.dgs-bc-premium-case {
    width: 100vw !important;
    max-width: 100vw !important;
    margin-left: calc(50% - 50vw) !important;
    margin-right: calc(50% - 50vw) !important;
    position: relative;
    overflow: hidden;
    color: #ffffff;
    background: #030407;
    font-family: Inter, Arial, sans-serif;
    padding: 100px 24px 90px;
    isolation: isolate;
  }

  .dgs-bc-premium-case * {
    box-sizing: border-box;
  }

  .dgs-bc-bg-wrap {
    position: absolute;
    inset: 0;
    overflow: hidden;
    z-index: 0;
    background:
      radial-gradient(circle at 12% 10%, rgba(255, 72, 86, 0.20), transparent 28%),
      radial-gradient(circle at 84% 16%, rgba(42, 152, 255, 0.18), transparent 32%),
      radial-gradient(circle at 48% 82%, rgba(219, 88, 255, 0.13), transparent 36%),
      linear-gradient(180deg, #030407 0%, #070914 48%, #030407 100%);
  }

  .dgs-bc-bg-grid {
    position: absolute;
    inset: 0;
    background-image:
      linear-gradient(rgba(255,255,255,0.035) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255,255,255,0.035) 1px, transparent 1px);
    background-size: 74px 74px;
    opacity: 0.16;
    mask-image: radial-gradient(circle at center, black 0%, transparent 78%);
    -webkit-mask-image: radial-gradient(circle at center, black 0%, transparent 78%);
  }

  .dgs-bc-bg-noise {
    position: absolute;
    inset: 0;
    opacity: 0.05;
    background-image:
      radial-gradient(circle at 20% 20%, rgba(255,255,255,0.7) 1px, transparent 1px),
      radial-gradient(circle at 70% 60%, rgba(255,255,255,0.45) 1px, transparent 1px);
    background-size: 140px 140px, 190px 190px;
    mix-blend-mode: screen;
  }

  .dgs-bc-orb {
    position: absolute;
    border-radius: 50%;
    filter: blur(90px);
    opacity: 0.48;
  }

  .dgs-bc-orb-red {
    width: 420px;
    height: 420px;
    background: #ff4656;
    top: -130px;
    left: -120px;
  }

  .dgs-bc-orb-blue {
    width: 460px;
    height: 460px;
    background: #2297ff;
    top: 160px;
    right: -170px;
  }

  .dgs-bc-orb-pink {
    width: 460px;
    height: 460px;
    background: #c75cff;
    bottom: 320px;
    left: 38%;
  }

  .dgs-bc-scan-light {
    position: absolute;
    width: 640px;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.65), transparent);
    filter: blur(14px);
    transform: rotate(-18deg);
    opacity: 0.28;
  }

  .dgs-bc-scan-one {
    top: 22%;
    left: -10%;
  }

  .dgs-bc-scan-two {
    bottom: 18%;
    right: -8%;
  }

  .dgs-bc-container {
    width: 100%;
    max-width: 1480px;
    margin: 0 auto;
    position: relative;
    z-index: 10;
  }

  .dgs-bc-pill {
    display: inline-flex;
    width: fit-content;
    align-items: center;
    justify-content: center;
    padding: 10px 16px;
    min-height: 36px;
    border-radius: 999px;
    color: #9dd6ff;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.14);
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.08);
    font-size: 12px;
    line-height: 1;
    font-weight: 900;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: 20px;
  }

  .dgs-bc-hero {
    min-height: 720px;
    display: grid;
    grid-template-columns: minmax(420px, 0.88fr) minmax(540px, 1.12fr);
    gap: 64px;
    align-items: center;
    padding: 20px 0 72px;
    position: relative;
    z-index: 5;
  }

  .dgs-bc-hero-content {
    position: relative !important;
    z-index: 20 !important;
    max-width: 780px !important;
    display: block !important;
    opacity: 1 !important;
    visibility: visible !important;
    transform: none !important;
  }

  .dgs-bc-hero-preview {
    position: relative;
    z-index: 3;
    opacity: 1 !important;
    visibility: visible !important;
    transform: none !important;
  }

  .dgs-bc-hero-content .dgs-bc-pill,
  .dgs-bc-hero-content h1,
  .dgs-bc-hero-content h2,
  .dgs-bc-hero-content p,
  .dgs-bc-actions,
  .dgs-bc-mini-stack {
    opacity: 1 !important;
    visibility: visible !important;
    transform: none !important;
  }

  .dgs-bc-hero-content h1 {
    margin: 0;
    color: #ffffff !important;
    font-size: clamp(52px, 5.7vw, 92px);
    line-height: 0.97;
    letter-spacing: -0.065em;
    font-weight: 850;
  }

  .dgs-bc-hero-content h1 span {
    display: block;
    margin-top: 10px;
    background: linear-gradient(90deg, #ffffff 0%, #86d7ff 36%, #e69aff 66%, #ff6270 100%);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }

  .dgs-bc-hero-content h2 {
    margin: 28px 0 20px;
    max-width: 740px;
    color: #edf2ff !important;
    font-size: clamp(24px, 2.3vw, 36px);
    line-height: 1.16;
    letter-spacing: -0.035em;
    font-weight: 760;
  }

  .dgs-bc-hero-content p,
  .dgs-bc-section p,
  .dgs-bc-card-content p,
  .dgs-bc-info-card p,
  .dgs-bc-process-item p,
  .dgs-bc-outcome p {
    margin: 0 0 18px;
    color: #b7c0d4 !important;
    font-size: 17px;
    line-height: 1.75;
    font-weight: 450;
  }

  .dgs-bc-actions {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    margin-top: 32px;
  }

  .dgs-bc-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 54px;
    padding: 15px 26px;
    border-radius: 999px;
    text-decoration: none;
    font-size: 14px;
    font-weight: 900;
    letter-spacing: 0.02em;
    transition: 0.22s ease;
  }

  .dgs-bc-btn-main {
    color: #ffffff;
    background: linear-gradient(135deg, #ff4d5c 0%, #d95cff 48%, #2ea2ff 100%);
    box-shadow: 0 18px 45px rgba(255, 77, 92, 0.25), 0 0 34px rgba(46, 162, 255, 0.18);
  }

  .dgs-bc-btn-main:hover {
    transform: translateY(-3px);
    box-shadow: 0 24px 58px rgba(255, 77, 92, 0.34), 0 0 44px rgba(46, 162, 255, 0.25);
  }

  .dgs-bc-btn-outline {
    color: #ffffff;
    background: rgba(255,255,255,0.055);
    border: 1px solid rgba(255,255,255,0.15);
  }

  .dgs-bc-btn-outline:hover {
    transform: translateY(-3px);
    background: rgba(255,255,255,0.1);
  }

  .dgs-bc-mini-stack {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 14px;
    max-width: 760px;
    margin-top: 32px;
  }

  .dgs-bc-mini-stack div,
  .dgs-bc-snapshot-card,
  .dgs-bc-browser,
  .dgs-bc-showcase-card,
  .dgs-bc-live-preview-card,
  .dgs-bc-info-card,
  .dgs-bc-process-item,
  .dgs-bc-outcome,
  .dgs-bc-final,
  .dgs-bc-ai-card {
    background:
      linear-gradient(145deg, rgba(255,255,255,0.09), rgba(255,255,255,0.03)),
      rgba(7,10,20,0.78);
    border: 1px solid rgba(255,255,255,0.12);
    box-shadow: 0 24px 70px rgba(0,0,0,0.32), inset 0 1px 0 rgba(255,255,255,0.06);
    backdrop-filter: blur(16px);
  }

  .dgs-bc-mini-stack div {
    border-radius: 20px;
    padding: 18px;
  }

  .dgs-bc-mini-stack span,
  .dgs-bc-snapshot-card span,
  .dgs-bc-browser-bottom span,
  .dgs-bc-ai-card span {
    display: block;
    color: #7e889f;
    font-size: 12px;
    font-weight: 850;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 8px;
  }

  .dgs-bc-mini-stack strong,
  .dgs-bc-snapshot-card strong,
  .dgs-bc-browser-bottom strong,
  .dgs-bc-ai-card strong {
    display: block;
    color: #ffffff;
    font-size: 16px;
    line-height: 1.35;
  }

  .dgs-bc-browser {
    border-radius: 32px;
    overflow: hidden;
    transform: none !important;
  }

  .dgs-bc-browser-top,
  .dgs-bc-card-top,
  .dgs-bc-preview-toolbar {
    min-height: 58px;
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 0 22px;
    background: rgba(3,5,12,0.86);
    border-bottom: 1px solid rgba(255,255,255,0.08);
  }

  .dgs-bc-browser-top strong {
    color: #aeb8cc;
    font-size: 14px;
    font-weight: 850;
    margin-right: auto;
  }

  .dgs-bc-browser-top a,
  .dgs-bc-card-top a,
  .dgs-bc-preview-toolbar a {
    color: #9dd6ff;
    text-decoration: none;
    font-size: 13px;
    font-weight: 900;
    margin-left: auto;
  }

  .dgs-bc-browser-top a:hover,
  .dgs-bc-card-top a:hover,
  .dgs-bc-preview-toolbar a:hover {
    color: #ffffff;
  }

  .dgs-bc-dots {
    display: flex;
    gap: 8px;
    flex-shrink: 0;
  }

  .dgs-bc-dots span {
    width: 12px;
    height: 12px;
    border-radius: 50%;
    display: block;
  }

  .dgs-bc-dots span:nth-child(1) {
    background: #ff4d5c;
  }

  .dgs-bc-dots span:nth-child(2) {
    background: #ffb24d;
  }

  .dgs-bc-dots span:nth-child(3) {
    background: #2ea2ff;
  }

  .dgs-bc-live-frame-wrap,
  .dgs-bc-big-frame,
  .dgs-bc-card-media {
    position: relative;
    width: 100%;
    overflow: hidden;
    background:
      linear-gradient(135deg, rgba(13,18,35,0.94), rgba(5,8,16,0.98));
  }

  .dgs-bc-live-frame-wrap {
    aspect-ratio: 16 / 10;
  }

  .dgs-bc-big-frame {
    height: min(760px, 78vh);
    min-height: 520px;
  }

  .dgs-bc-card-media {
    aspect-ratio: 16 / 10;
  }

  .dgs-bc-showcase-large .dgs-bc-card-media {
    aspect-ratio: 16 / 13;
  }

  .dgs-bc-live-frame-wrap iframe,
  .dgs-bc-big-frame iframe,
  .dgs-bc-card-media iframe,
  .dgs-bc-device-desktop iframe,
  .dgs-bc-device-mobile iframe {
    width: 100%;
    height: 100%;
    border: 0;
    display: block;
    background: #070b14;
    position: relative;
    z-index: 2;
  }

  .dgs-bc-frame-fallback {
    position: absolute;
    inset: 0;
    z-index: 1;
    display: grid;
    place-content: center;
    text-align: center;
    padding: 28px;
    background:
      radial-gradient(circle at 30% 20%, rgba(46,162,255,0.18), transparent 34%),
      radial-gradient(circle at 80% 70%, rgba(255,77,92,0.16), transparent 34%),
      linear-gradient(135deg, rgba(14,20,38,0.98), rgba(5,8,16,0.98));
  }

  .dgs-bc-frame-fallback span {
    color: #9dd6ff;
    font-size: 13px;
    font-weight: 900;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 12px;
  }

  .dgs-bc-frame-fallback h3 {
    margin: 0 0 12px;
    color: #ffffff;
    font-size: clamp(28px, 4vw, 50px);
    line-height: 1;
    letter-spacing: -0.05em;
  }

  .dgs-bc-frame-fallback p {
    max-width: 520px;
    margin: 0 auto 22px;
    color: #b7c0d4;
    font-size: 16px;
    line-height: 1.65;
  }

  .dgs-bc-frame-fallback a {
    display: inline-flex;
    width: fit-content;
    margin: 0 auto;
    color: #ffffff;
    text-decoration: none;
    font-weight: 900;
    padding: 13px 20px;
    border-radius: 999px;
    background: linear-gradient(135deg, #ff4d5c, #2ea2ff);
  }

  .dgs-bc-browser-bottom {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1px;
    background: rgba(255,255,255,0.06);
  }

  .dgs-bc-browser-bottom div {
    padding: 22px;
    background: rgba(4,6,14,0.68);
  }

  .dgs-bc-ai-optimization-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-top: 18px;
    position: relative;
    z-index: 5;
  }

  .dgs-bc-ai-card {
    border-radius: 20px;
    padding: 18px;
    min-height: 108px;
    transition: 0.22s ease;
  }

  .dgs-bc-ai-card:hover {
    transform: translateY(-4px);
    border-color: rgba(46,162,255,0.34);
  }

  .dgs-bc-snapshot {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 18px;
    margin: 0 0 96px;
  }

  .dgs-bc-snapshot-card {
    border-radius: 22px;
    padding: 24px;
    transition: 0.22s ease;
  }

  .dgs-bc-snapshot-card:hover {
    transform: translateY(-5px);
    border-color: rgba(46,162,255,0.34);
  }

  .dgs-bc-section {
    margin-bottom: 96px;
  }

  .dgs-bc-two-col {
    display: grid;
    grid-template-columns: minmax(300px, 0.9fr) minmax(0, 1.1fr);
    gap: 70px;
    align-items: start;
  }

  .dgs-bc-two-col h2,
  .dgs-bc-center-head h2,
  .dgs-bc-outcome h2,
  .dgs-bc-final h2 {
    margin: 0 0 20px;
    color: #ffffff;
    font-size: clamp(34px, 4.2vw, 60px);
    line-height: 1.08;
    letter-spacing: -0.05em;
    font-weight: 850;
  }

  .dgs-bc-text-link {
    display: inline-flex;
    margin-top: 8px;
    color: #9dd6ff;
    text-decoration: none;
    font-size: 16px;
    font-weight: 900;
    border-bottom: 1px solid rgba(157,214,255,0.5);
  }

  .dgs-bc-text-link:hover {
    color: #ffffff;
    border-color: #ffffff;
  }

  .dgs-bc-center-head {
    max-width: 920px;
    text-align: center;
    margin: 0 auto 42px;
  }

  .dgs-bc-center-head p {
    margin-left: auto;
    margin-right: auto;
  }

  .dgs-bc-live-preview-card {
    border-radius: 32px;
    overflow: hidden;
    transform: none !important;
  }

  .dgs-bc-url-bar {
    flex: 1;
    min-width: 0;
    padding: 10px 14px;
    border-radius: 999px;
    color: #aeb8cc;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.08);
    font-size: 13px;
    font-weight: 800;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .dgs-bc-showcase-grid {
    display: grid;
    grid-template-columns: 1.15fr 0.85fr;
    gap: 24px;
  }

  .dgs-bc-showcase-card {
    border-radius: 28px;
    overflow: hidden;
    transition: 0.22s ease;
    transform: none !important;
  }

  .dgs-bc-showcase-card:hover {
    transform: translateY(-4px) !important;
    border-color: rgba(255,77,92,0.34);
  }

  .dgs-bc-showcase-large {
    grid-row: span 2;
  }

  .dgs-bc-showcase-wide {
    grid-column: 1 / -1;
  }

  .dgs-bc-card-top {
    justify-content: space-between;
  }

  .dgs-bc-card-top span {
    color: #ffffff;
    font-size: 14px;
    font-weight: 900;
  }

  .dgs-bc-card-content {
    padding: 28px;
  }

  .dgs-bc-card-content h3,
  .dgs-bc-info-card h3,
  .dgs-bc-process-item h3 {
    margin: 0 0 12px;
    color: #ffffff;
    font-size: 22px;
    line-height: 1.24;
    letter-spacing: -0.02em;
  }

  .dgs-bc-static-preview {
    min-height: 330px;
    padding: 34px;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    background:
      radial-gradient(circle at 20% 20%, rgba(46,162,255,0.22), transparent 30%),
      radial-gradient(circle at 80% 70%, rgba(255,77,92,0.18), transparent 30%),
      linear-gradient(135deg, #0b1020, #040711);
  }

  .dgs-bc-static-preview span {
    width: fit-content;
    color: #9dd6ff;
    font-size: 12px;
    font-weight: 900;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: 14px;
  }

  .dgs-bc-static-preview h3 {
    margin: 0 0 12px;
    color: #ffffff;
    font-size: 34px;
    line-height: 1.04;
    letter-spacing: -0.045em;
  }

  .dgs-bc-static-preview p {
    margin: 0;
    color: #b7c0d4;
    font-size: 15.5px;
    line-height: 1.65;
  }

  .dgs-bc-static-two {
    background:
      radial-gradient(circle at 78% 20%, rgba(219,88,255,0.2), transparent 28%),
      radial-gradient(circle at 18% 82%, rgba(46,162,255,0.2), transparent 30%),
      linear-gradient(135deg, #0b1020, #040711);
  }

  .dgs-bc-device-stage {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 250px;
    gap: 28px;
    align-items: end;
    padding: 32px;
    background:
      radial-gradient(circle at 78% 20%, rgba(255,77,92,0.11), transparent 30%),
      radial-gradient(circle at 18% 80%, rgba(46,162,255,0.11), transparent 34%),
      rgba(5,8,16,0.94);
  }

  .dgs-bc-device-desktop,
  .dgs-bc-device-mobile {
    position: relative;
    overflow: hidden;
    background: #08101b;
    border: 10px solid rgba(255,255,255,0.07);
    box-shadow: 0 24px 70px rgba(0,0,0,0.35);
  }

  .dgs-bc-device-desktop {
    aspect-ratio: 16 / 9;
    border-radius: 22px;
  }

  .dgs-bc-device-mobile {
    aspect-ratio: 9 / 16;
    border-radius: 32px;
  }

  .dgs-bc-panel {
    padding: 52px;
    border-radius: 34px;
    background:
      linear-gradient(145deg, rgba(255,255,255,0.06), rgba(255,255,255,0.025)),
      rgba(6,9,18,0.75);
    border: 1px solid rgba(255,255,255,0.11);
    box-shadow: 0 28px 80px rgba(0,0,0,0.28), inset 0 1px 0 rgba(255,255,255,0.05);
  }

  .dgs-bc-grid-4 {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 18px;
  }

  .dgs-bc-info-card {
    border-radius: 24px;
    padding: 28px;
    transition: 0.22s ease;
  }

  .dgs-bc-info-card:hover {
    transform: translateY(-4px);
    border-color: rgba(46,162,255,0.3);
  }

  .dgs-bc-info-card > strong {
    display: inline-flex;
    margin-bottom: 16px;
    color: #ff6472;
    font-size: 15px;
    font-weight: 950;
  }

  .dgs-bc-list {
    list-style: none;
    padding: 0;
    margin: 24px 0 0;
    display: grid;
    gap: 14px;
  }

  .dgs-bc-list li {
    position: relative;
    padding-left: 34px;
    color: #d4dceb;
    font-size: 16px;
    line-height: 1.65;
  }

  .dgs-bc-list li::before {
    content: "✓";
    position: absolute;
    left: 0;
    top: 2px;
    width: 22px;
    height: 22px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    color: #ffffff;
    font-size: 12px;
    font-weight: 900;
    background: linear-gradient(135deg, #ff4d5c, #2ea2ff);
  }

  .dgs-bc-tech-grid {
    display: grid;
    grid-template-columns: repeat(9, 1fr);
    gap: 14px;
  }

  .dgs-bc-tech-grid div {
    min-height: 76px;
    display: grid;
    place-items: center;
    text-align: center;
    padding: 14px;
    border-radius: 18px;
    color: #ffffff;
    font-size: 15px;
    font-weight: 900;
    background:
      linear-gradient(145deg, rgba(255,255,255,0.08), rgba(255,255,255,0.03)),
      rgba(9,12,22,0.78);
    border: 1px solid rgba(255,255,255,0.1);
    transition: 0.22s ease;
  }

  .dgs-bc-tech-grid div:hover {
    transform: translateY(-4px);
    border-color: rgba(255,77,92,0.34);
  }

  .dgs-bc-process-list {
    display: grid;
    gap: 18px;
  }

  .dgs-bc-process-item {
    display: grid;
    grid-template-columns: 76px 1fr;
    gap: 22px;
    padding: 28px;
    border-radius: 24px;
    transition: 0.22s ease;
  }

  .dgs-bc-process-item:hover {
    transform: translateX(4px);
    border-color: rgba(46,162,255,0.3);
  }

  .dgs-bc-process-item > span {
    width: 56px;
    height: 56px;
    display: grid;
    place-items: center;
    border-radius: 18px;
    color: #ffffff;
    font-size: 16px;
    font-weight: 900;
    background: linear-gradient(135deg, #ff4d5c, #2ea2ff);
    box-shadow: 0 18px 38px rgba(255,77,92,0.18);
  }

  .dgs-bc-outcome {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 46px;
    align-items: center;
    padding: 52px;
    border-radius: 34px;
  }

  .dgs-bc-outcome-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
  }

  .dgs-bc-outcome-grid div {
    padding: 24px;
    min-height: 145px;
    border-radius: 22px;
    background: rgba(255,255,255,0.05);
