      radial-gradient(circle at 85% 20%, rgba(255,77,92,0.12), transparent 26%),
      radial-gradient(circle at 10% 80%, rgba(46,162,255,0.12), transparent 30%),
      linear-gradient(145deg, rgba(255,255,255,0.08), rgba(255,255,255,0.03)),
      rgba(8,10,18,0.82);
