    }
  }

  @media (max-width: 767px) {
    .dgs-bc-premium-case {
      padding: 78px 16px 64px;
    }

    .dgs-bc-hero {
      padding: 10px 0 42px;
      gap: 36px;
    }

    .dgs-bc-hero-content h1 {
      font-size: 44px;
      letter-spacing: -0.055em;
    }

    .dgs-bc-hero-content h2 {
      font-size: 24px;
      line-height: 1.18;
