    }

    .dgs-bc-btn {
      width: 100%;
    }

    .dgs-bc-mini-stack,
    .dgs-bc-snapshot,
    .dgs-bc-grid-4,
    .dgs-bc-tech-grid,
    .dgs-bc-outcome-grid,
    .dgs-bc-ai-optimization-grid {
