/* ========================================
   FAQ SECTION - BASE STYLES
======================================== */

.wdgs-faq-section,
.wdgs-faq-section *,
.wdgs-faq-section *::before,
.wdgs-faq-section *::after {
  background-image: none !important;
  box-sizing: border-box;
}

.wdgs-faq-section {
  position: relative;
  width: 100%;
  padding: 120px 20px;
  background: #000000 !important;
  overflow: hidden;
}

.wdgs-faq-container {
  position: relative;
  max-width: 900px;
  margin: 0 auto;
  z-index: 10;
}

/* ========================================
   HEADER
======================================== */

.wdgs-faq-header {
  text-align: center;
  margin-bottom: 80px;
}

.wdgs-faq-subtitle {
  font-size: clamp(14px, 2vw, 16px);
  font-weight: 600;
  color: rgba(255, 255, 255, 0.6) !important;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  margin: 0 0 16px 0;
}

.wdgs-faq-title {
  font-size: clamp(42px, 7vw, 72px);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin: 0 0 24px 0;
  display: block;
}

.wdgs-faq-gradient-pink {
  display: block;
  background: linear-gradient(135deg, #ea3f8b, #ff6b9d) !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
}

.wdgs-faq-gradient-orange {
  display: block;
  background: linear-gradient(135deg, #72c1d8, #634dbc) !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
}

.wdgs-faq-description {
  font-size: clamp(16px, 2.5vw, 18px);
  color: rgba(255, 255, 255, 0.7) !important;
  line-height: 1.7;
  max-width: 680px;
  margin: 0 auto;
}

/* ========================================
   ACCORDION
======================================== */

.wdgs-faq-accordion {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.wdgs-faq-item {
  background: transparent !important;
  border: 1.5px solid rgba(255, 255, 255, 0.1) !important;
  border-radius: 20px;
  overflow: hidden;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  contain: layout style paint;
}

.wdgs-faq-item:hover {
  border-color: rgba(234, 63, 139, 0.4) !important;
  transform: translateY(-2px);
  box-shadow: 0 0 30px rgba(234, 63, 139, 0.15) !important;
}

.wdgs-faq-item-active {
  background: rgba(234, 63, 139, 0.02) !important;
  border-color: rgba(234, 63, 139, 0.6) !important;
  box-shadow: 0 0 40px rgba(234, 63, 139, 0.25) !important;
}

.wdgs-faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 28px 32px;
  background: transparent !important;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: all 0.3s ease;
  position: relative;
  min-height: 48px;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

.wdgs-faq-question::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  width: 3px;
  height: 100%;
  background: linear-gradient(180deg, transparent, rgba(234, 63, 139, 0.5), transparent) !important;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.wdgs-faq-item:hover .wdgs-faq-question::before,
.wdgs-faq-item-active .wdgs-faq-question::before {
  opacity: 1;
}

.wdgs-faq-question-text {
  font-size: clamp(17px, 2.5vw, 20px);
  font-weight: 700;
  color: rgba(255, 255, 255, 0.95) !important;
  line-height: 1.4;
  flex: 1;
  transition: color 0.3s ease;
}

.wdgs-faq-item:hover .wdgs-faq-question-text {
  color: rgba(255, 255, 255, 1) !important;
}

.wdgs-faq-item-active .wdgs-faq-question-text {
  background: linear-gradient(135deg, #ea3f8b, #ff6b9d) !important;
  -webkit-background-clip: text !important;
  -webkit-text-fill-color: transparent !important;
  background-clip: text !important;
}

.wdgs-faq-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  min-width: 36px;
  background: transparent !important;
  border: 1.5px solid rgba(255, 255, 255, 0.2) !important;
  border-radius: 50%;
  flex-shrink: 0;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.wdgs-faq-item:hover .wdgs-faq-icon {
  border-color: rgba(234, 63, 139, 0.5) !important;
  background: rgba(234, 63, 139, 0.05) !important;
}

.wdgs-faq-icon svg {
  color: rgba(255, 255, 255, 0.7) !important;
  transition: all 0.3s ease;
}

.wdgs-faq-item:hover .wdgs-faq-icon svg {
  color: rgba(234, 63, 139, 0.9) !important;
}

.wdgs-faq-icon-horizontal {
  transition: opacity 0.3s ease, transform 0.3s ease;
}

.wdgs-faq-item-active .wdgs-faq-icon {
  border-color: rgba(234, 63, 139, 0.8) !important;
  background: rgba(234, 63, 139, 0.1) !important;
  transform: rotate(180deg);
}

.wdgs-faq-item-active .wdgs-faq-icon svg {
  color: #ea3f8b !important;
}

.wdgs-faq-item-active .wdgs-faq-icon-horizontal {
  opacity: 0;
  transform: rotate(90deg);
}

.wdgs-faq-answer {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.wdgs-faq-item-active .wdgs-faq-answer {
  grid-template-rows: 1fr;
}

.wdgs-faq-answer-content {
  overflow: hidden;
  padding: 0 32px 0 32px;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
}

.wdgs-faq-item-active .wdgs-faq-answer-content {
  padding: 24px 32px 32px 32px;
}

.wdgs-faq-answer-content p {
  font-size: clamp(15px, 2vw, 17px);
  color: rgba(255, 255, 255, 0.75) !important;
  line-height: 1.8;
  margin: 0;
}

/* ========================================
   CONTACT FORM SECTION
======================================== */

.wdgs-faq-contact-section {
  position: relative;
  padding: 100px 20px 0;
  z-index: 10;
}

.wdgs-faq-contact-container {
  max-width: 800px;
  margin: 0 auto;
}

.wdgs-faq-contact-glass {
  background: transparent !important;
  border: 1.5px solid rgba(255, 255, 255, 0.1) !important;
  border-radius: 32px;
  padding: 60px;
  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.4) !important;
  transition: all 0.4s ease;
  position: relative;
  overflow: visible !important;
}

.wdgs-faq-contact-glass::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 0%, rgba(234, 63, 139, 0.08) 0%, transparent 60%) !important;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.4s ease;
  border-radius: 32px;
}

.wdgs-faq-contact-glass:hover {
  border-color: rgba(234, 63, 139, 0.4) !important;
  transform: translateY(-4px);
  box-shadow: 0 32px 80px rgba(0, 0, 0, 0.5), 0 0 60px rgba(234, 63, 139, 0.15) !important;
}

.wdgs-faq-contact-glass:hover::before {
  opacity: 1;
}

.wdgs-faq-contact-header {
  text-align: center;
  margin-bottom: 48px;
  position: relative;
  z-index: 2;
}

.wdgs-faq-contact-title {
  font-size: clamp(32px, 5vw, 48px);
  font-weight: 800;
  color: rgba(255, 255, 255, 0.98) !important;
  margin: 0 0 16px 0;
  line-height: 1.2;
}

.wdgs-faq-contact-subtitle {
  font-size: clamp(15px, 2vw, 17px);
  color: rgba(255, 255, 255, 0.7) !important;
  line-height: 1.7;
  margin: 0 0 24px 0;
}

.wdgs-faq-contact-line {
  width: 100px;
  height: 3px;
  background: linear-gradient(90deg, #ea3f8b, #ff6b9d) !important;
  margin: 0 auto;
  border-radius: 10px;
}

.wdgs-faq-form-wrapper {
  position: relative;
  z-index: 2;
}

/* ========================================
   FLUENT FORM - ALL FIELDS
======================================== */

.wdgs-faq-form-wrapper .ff-el-group {
  margin-bottom: 24px;
  position: relative;
}

.wdgs-faq-form-wrapper .ff-el-form-control,
.wdgs-faq-form-wrapper input[type="text"],
.wdgs-faq-form-wrapper input[type="email"],
.wdgs-faq-form-wrapper input[type="tel"],
.wdgs-faq-form-wrapper textarea,
.wdgs-faq-form-wrapper select {
  background: rgba(255, 255, 255, 0.03) !important;
  border: 1.5px solid rgba(255, 255, 255, 0.12) !important;
  border-radius: 12px !important;
  color: rgba(255, 255, 255, 0.95) !important;
  font-size: 15px !important;
  padding: 14px 18px !important;
  width: 100% !important;
  transition: all 0.3s ease !important;
  -webkit-appearance: none;
  appearance: none;
}

.wdgs-faq-form-wrapper .ff-el-form-control:focus,
.wdgs-faq-form-wrapper input:focus,
.wdgs-faq-form-wrapper textarea:focus,
.wdgs-faq-form-wrapper select:focus {
  background: rgba(255, 255, 255, 0.05) !important;
  border-color: rgba(234, 63, 139, 0.5) !important;
  box-shadow: 0 0 0 3px rgba(234, 63, 139, 0.1) !important;
  outline: none !important;
}

.wdgs-faq-form-wrapper ::placeholder {
  color: rgba(255, 255, 255, 0.4) !important;
}

.wdgs-faq-form-wrapper textarea {
  min-height: 140px !important;
  resize: vertical !important;
}

.wdgs-faq-form-wrapper .ff-el-input--label label,
.wdgs-faq-form-wrapper label {
  color: rgba(255, 255, 255, 0.85) !important;
  font-weight: 600 !important;
  font-size: 14px !important;
  margin-bottom: 8px !important;
  display: block !important;
}

.wdgs-faq-form-wrapper .ff-el-is-error .ff-el-form-control {
  border-color: #ff4444 !important;
}

.wdgs-faq-form-wrapper .error {
  color: #ff6666 !important;
  font-size: 13px !important;
  margin-top: 6px !important;
}

/* ========================================
   PHONE FIELD
======================================== */

.wdgs-faq-form-wrapper .iti {
  width: 100% !important;
  display: block !important;
  position: relative !important;
}

.wdgs-faq-form-wrapper .iti__flag-container {
  display: flex !important;
  align-items: center !important;
  background: rgba(255, 255, 255, 0.05) !important;
  border-right: 1.5px solid rgba(255, 255, 255, 0.12) !important;
  position: absolute !important;
  top: 0 !important;
  bottom: 0 !important;
  left: 0 !important;
  z-index: 3 !important;
  width: auto !important;
}

.wdgs-faq-form-wrapper .iti__selected-flag {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  padding: 0 10px 0 14px !important;
  background: transparent !important;
  border: none !important;
  height: 100% !important;
  min-width: 70px !important;
}

.wdgs-faq-form-wrapper .iti__flag {
  display: inline-block !important;
  width: 20px !important;
  height: 15px !important;
  background-image: url('https://cdnjs.cloudflare.com/ajax/libs/intl-tel-input/17.0.19/img/flags.png') !important;
}

@media (-webkit-min-device-pixel-ratio: 2), (min-resolution: 192dpi) {
  .wdgs-faq-form-wrapper .iti__flag {
    background-image: url('https://cdnjs.cloudflare.com/ajax/libs/intl-tel-input/17.0.19/img/flags@2x.png') !important;
