  }
}

.wdgs-faq-form-wrapper .iti__selected-dial-code {
  color: rgba(255, 255, 255, 0.9) !important;
  font-size: 15px !important;
  font-weight: 500 !important;
}

.wdgs-faq-form-wrapper .iti__arrow {
  border-top: 4px solid rgba(255, 255, 255, 0.7) !important;
  border-left: 3px solid transparent !important;
  border-right: 3px solid transparent !important;
}

.wdgs-faq-form-wrapper input[type="tel"].iti__tel-input {
  padding-left: 85px !important;
}

.wdgs-faq-form-wrapper .iti__country-list,
.iti__country-list {
  background: rgba(20, 20, 20, 0.98) !important;
