}

.wdgs-faq-form-wrapper .iti__search-input,
.iti__search-input {
  background: rgba(255, 255, 255, 0.05) !important;
  border: 1px solid rgba(234, 63, 139, 0.3) !important;
  border-radius: 8px !important;
  color: rgba(255, 255, 255, 0.95) !important;
