}

.wdgs-faq-form-wrapper .iti__country-name,
.iti__country-name,
.wdgs-faq-form-wrapper .iti__dial-code,
.iti__dial-code {
  color: rgba(255, 255, 255, 0.9) !important;
}

.wdgs-faq-form-wrapper .iti__country:hover,
.iti__country:hover,
.wdgs-faq-form-wrapper .iti__country.iti__highlight,
.iti__country.iti__highlight {
  background: rgba(234, 63, 139, 0.2) !important;
}

