    background:
      radial-gradient(circle at 10% 20%, rgba(255,77,92,0.12), transparent 28%),
      radial-gradient(circle at 88% 78%, rgba(46,162,255,0.14), transparent 32%),
      linear-gradient(145deg, rgba(255,255,255,0.07), rgba(255,255,255,0.025)),
