  }

  .dgs-bc-form-wrapper ::placeholder {
    color: rgba(255,255,255,0.42) !important;
  }

  .dgs-bc-form-wrapper .ff-el-input--label label,
  .dgs-bc-form-wrapper label {
    display: block !important;
    margin-bottom: 8px !important;
    color: rgba(255,255,255,0.86) !important;
    font-size: 14px !important;
    font-weight: 700 !important;
  }

  .dgs-bc-form-wrapper .ff-el-is-error .ff-el-form-control {
    border-color: #ff4d5c !important;
  }

  .dgs-bc-form-wrapper .error,
  .dgs-bc-form-wrapper .text-danger {
    color: #ff6b76 !important;
    font-size: 13px !important;
    margin-top: 6px !important;
  }

  .dgs-bc-form-wrapper .iti {
    width: 100% !important;
    display: block !important;
  }

  .dgs-bc-form-wrapper .iti__flag-container {
    background: rgba(255,255,255,0.055) !important;
    border-right: 1.5px solid rgba(255,255,255,0.12) !important;
  }

  .dgs-bc-form-wrapper .iti__selected-flag {
    background: transparent !important;
    min-width: 72px !important;
    padding: 0 10px 0 14px !important;
  }

  .dgs-bc-form-wrapper .iti__selected-dial-code {
    color: rgba(255,255,255,0.9) !important;
    font-size: 14px !important;
    font-weight: 600 !important;
  }

  .dgs-bc-form-wrapper input[type="tel"].iti__tel-input {
    padding-left: 88px !important;
  }

  .dgs-bc-form-wrapper .iti__country-list,
  .iti__country-list {
    background: rgba(12,14,22,0.98) !important;
    border: 1.5px solid rgba(46,162,255,0.28) !important;
    border-radius: 14px !important;
    box-shadow: 0 18px 48px rgba(0,0,0,0.8) !important;
    z-index: 99999 !important;
  }

  .dgs-bc-form-wrapper .iti__country,
  .iti__country {
    color: rgba(255,255,255,0.9) !important;
    padding: 12px 16px !important;
  }

  .dgs-bc-form-wrapper .iti__country:hover,
  .iti__country:hover,
  .dgs-bc-form-wrapper .iti__country.iti__highlight,
  .iti__country.iti__highlight {
    background: rgba(46,162,255,0.18) !important;
  }

  .dgs-bc-form-wrapper .select2-container {
    width: 100% !important;
  }

  .dgs-bc-form-wrapper .select2-container--default .select2-selection--single {
    min-height: 50px !important;
    border-radius: 14px !important;
    background: rgba(255,255,255,0.045) !important;
    border: 1.5px solid rgba(255,255,255,0.12) !important;
    display: flex !important;
    align-items: center !important;
  }

  .dgs-bc-form-wrapper .select2-container--default .select2-selection--single .select2-selection__rendered {
    color: rgba(255,255,255,0.95) !important;
    padding-left: 18px !important;
    line-height: 50px !important;
  }

  .dgs-bc-form-wrapper .select2-container--default .select2-selection--single .select2-selection__arrow {
    height: 50px !important;
  }

  .dgs-bc-form-wrapper .ff-btn-submit,
  .dgs-bc-form-wrapper .ff_submit_btn,
  .dgs-bc-form-wrapper button[type="submit"],
  .dgs-bc-form-wrapper input[type="submit"] {
    width: 100% !important;
    min-height: 54px !important;
    margin-top: 10px !important;
    padding: 15px 26px !important;
    border: none !important;
    border-radius: 999px !important;
    color: #ffffff !important;
    background: linear-gradient(135deg, #ff4d5c 0%, #d95cff 48%, #2ea2ff 100%) !important;
    box-shadow:
      0 18px 45px rgba(255,77,92,0.25),
      0 0 34px rgba(46,162,255,0.18) !important;
    font-size: 14px !important;
    font-weight: 900 !important;
    letter-spacing: 0.06em !important;
    text-transform: uppercase !important;
    cursor: pointer !important;
    transition: 0.25s ease !important;
  }

  .dgs-bc-form-wrapper .ff-btn-submit:hover,
  .dgs-bc-form-wrapper button[type="submit"]:hover,
  .dgs-bc-form-wrapper input[type="submit"]:hover {
    transform: translateY(-3px) !important;
    box-shadow:
      0 24px 58px rgba(255,77,92,0.34),
      0 0 44px rgba(46,162,255,0.25) !important;
  }

  @media (max-width: 1024px) {
    .dgs-bc-contact-wrap {
      grid-template-columns: 1fr;
      gap: 34px;
    }
  }

  @media (max-width: 767px) {
    .dgs-bc-contact-wrap {
      padding: 26px;
      border-radius: 26px;
    }

    .dgs-bc-contact-card {
      padding: 24px;
      border-radius: 22px;
    }

    .dgs-bc-contact-left h2 {
      font-size: 30px;
      letter-spacing: -0.04em;
    }

    .dgs-bc-contact-header h3 {
      font-size: 28px;
    }

    .dgs-bc-form-wrapper .ff-el-form-control,
    .dgs-bc-form-wrapper input,
    .dgs-bc-form-wrapper textarea,
    .dgs-bc-form-wrapper select {
      font-size: 16px !important;
    }

    .dgs-bc-form-wrapper input[type="tel"].iti__tel-input {
      padding-left: 82px !important;
    }
  }

/* ========================================
   FOOTER - LIGHTWEIGHT & SEXY DESIGN
   ======================================== */

.dgs-footer-wrapper * {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

.dgs-footer-wrapper {
  position: relative;
  background: transparent;
  padding: 0;
  margin: 0;
  font-family: 'Space Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  overflow: hidden;
}

.dgs-footer {
  position: relative;
  background: transparent;
  border-top: 1px solid rgba(255, 255, 255, 0.05);
  padding: clamp(60px, 8vw, 100px) clamp(20px, 4vw, 40px) 0;
  color: #fff;
  overflow: hidden;
}

.dgs-footer-container {
  max-width: 1600px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.dgs-footer-grid {
  display: grid;
  grid-template-columns: 1.2fr repeat(3, 1fr);
  gap: clamp(30px, 4vw, 40px);
  margin-bottom: clamp(40px, 5vw, 55px);
}

.dgs-footer-column {
  display: flex;
  flex-direction: column;
}

.dgs-footer-logo-column {
  max-width: 280px;
}

.dgs-footer-logo {
  display: block;
  width: clamp(130px, 15vw, 160px);
  height: auto;
  margin-bottom: 22px;
  transition: transform 0.4s ease;
  opacity: 0.95;
}

.dgs-footer-logo:hover {
  transform: scale(1.03);
  opacity: 1;
}

.dgs-footer-tagline {
  font-size: clamp(0.8rem, 1.2vw, 0.88rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.5);
  letter-spacing: 0.3px;
  margin-top: 0;
  margin-bottom: 22px;
  line-height: 1.7;
}

.dgs-footer-column-title {
  font-size: clamp(0.95rem, 1.5vw, 1.1rem);
  font-weight: 400;
  color: rgba(255, 255, 255, 0.95);
  margin-bottom: clamp(16px, 2vw, 20px);
  letter-spacing: 0.5px;
  position: relative;
  display: inline-block;
  width: fit-content;
}

.dgs-footer-column-title::after {
  content: '';
  position: absolute;
  bottom: -6px;
  left: 0;
  width: 30px;
  height: 1px;
  background: linear-gradient(90deg, #00D4FF 0%, #FF00DC 50%, #FF6B35 100%);
  border-radius: 10px;
  opacity: 0.6;
}

.dgs-footer-links {
  list-style: none;
  padding: 0;
  margin: 0;
}

.dgs-footer-link-item {
  margin-bottom: 8px;
}

.dgs-footer-link {
  display: inline-block;
  font-size: clamp(0.82rem, 1.2vw, 0.9rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.55);
  text-decoration: none;
  transition: all 0.3s ease;
  position: relative;
  padding-left: 0;
  letter-spacing: 0.3px;
}

.dgs-footer-link::before {
  content: '→';
  position: absolute;
  left: -18px;
  opacity: 0;
  color: #FF6B35;
  transition: all 0.3s ease;
  font-weight: 300;
}

.dgs-footer-link:hover {
  color: rgba(255, 255, 255, 0.95);
  padding-left: 18px;
}

.dgs-footer-link:hover::before {
  opacity: 1;
  left: 0;
}

.dgs-footer-contact-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 14px;
  font-size: clamp(0.82rem, 1.2vw, 0.9rem);
  font-weight: 300;
  color: rgba(255, 255, 255, 0.65);
  line-height: 1.7;
}

.dgs-footer-contact-item div {
  text-align: left;
}

.dgs-footer-contact-icon {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  margin-top: 3px;
  opacity: 1;
  background: transparent !important;
}

.dgs-footer-contact-icon path {
  fill: none !important;
  background: none !important;
}

.dgs-footer-contact-item strong {
  font-weight: 400;
  color: rgba(255, 255, 255, 0.85);
}

.dgs-footer-contact-link {
  color: rgba(255, 255, 255, 0.65);
  text-decoration: none;
  transition: all 0.3s ease;
  display: block;
  margin-bottom: 6px;
  font-weight: 300;
}

.dgs-footer-contact-link:hover {
  color: rgba(255, 255, 255, 0.95);
  padding-left: 6px;
}

.dgs-footer-map-container {
  margin-top: 12px;
  max-height: 0;
  overflow: hidden;
  opacity: 0;
  transition: all 0.5s ease;
  border-radius: 12px;
}

.dgs-footer-map-container.active {
  max-height: 350px;
  opacity: 1;
  margin-top: 16px;
}

.dgs-footer-map-container iframe {
  width: 100%;
  height: 300px;
  border: 0;
  border-radius: 12px;
  display: block;
}

.dgs-footer-address-clickable {
  cursor: pointer;
  transition: all 0.3s ease;
}

.dgs-footer-address-clickable:hover {
  color: rgba(255, 255, 255, 0.95);
}

.dgs-footer-address-clickable strong {
  position: relative;
  display: inline-block;
}

.dgs-footer-address-clickable strong::after {
  content: ' ↗';
  font-size: 0.85em;
  opacity: 0.6;
  transition: all 0.3s ease;
}

.dgs-footer-address-clickable:hover strong::after {
  opacity: 1;
  transform: translateX(2px) translateY(-2px);
}

.dgs-footer-social {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 0;
}

.dgs-footer-social-link {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 10px;
  color: rgba(255, 255, 255, 0.6);
  text-decoration: none;
  transition: all 0.4s ease;
}

.dgs-footer-social-link:hover {
  background: transparent;
  border-color: rgba(255, 107, 53, 0.5);
  transform: translateY(-3px);
  box-shadow: 0 6px 20px rgba(255, 107, 53, 0.15);
  color: rgba(255, 255, 255, 0.95);
}

.dgs-footer-social-icon {
  width: 18px;
  height: 18px;
}

.dgs-footer-stalk-box {
  margin-top: 18px;
  width: 100%;
}

.dgs-footer-stalk-title {
  font-size: clamp(0.82rem, 1.2vw, 0.92rem);
  font-weight: 500;
  color: rgba(255, 255, 255, 0.82);
  letter-spacing: 0.3px;
  margin-bottom: 12px;
  line-height: 1.35;
}

.dgs-footer-contact-column .dgs-footer-social {
  justify-content: flex-start;
}

.dgs-footer-contact-column .dgs-footer-social-link {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.035);
}

/* AI Summary Shortcut Icons - Latest Brand Icons */
.dgs-footer-ai-summary {
  margin: 0 0 22px;
  width: 100%;
}

.dgs-footer-ai-heading {
  font-size: clamp(0.76rem, 1.1vw, 0.84rem);
  font-weight: 400;
  color: rgba(255, 255, 255, 0.72);
  letter-spacing: 0.25px;
  margin-bottom: 10px;
  line-height: 1.45;
}

.dgs-footer-ai-icons {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.dgs-footer-ai-link {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.065);
  text-decoration: none;
  transition: all 0.35s ease;
  position: relative;
  overflow: hidden;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.dgs-footer-ai-link::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.18), rgba(255, 0, 220, 0.14), rgba(255, 107, 53, 0.18));
  opacity: 0;
  transition: opacity 0.35s ease;
}

.dgs-footer-ai-link:hover {
  transform: translateY(-3px);
  border-color: rgba(255, 107, 53, 0.55);
  box-shadow: 0 8px 24px rgba(255, 107, 53, 0.18);
}

.dgs-footer-ai-link:hover::before {
  opacity: 1;
}

.dgs-footer-ai-icon {
  position: relative;
  z-index: 1;
  width: 19px;
  height: 19px;
  display: block;
  object-fit: contain;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.22));
}

.dgs-footer-ai-fallback {
  position: relative;
  z-index: 1;
  display: none;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: rgba(255, 255, 255, 0.92);
  font-size: 0.68rem;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.2px;
}

.dgs-ai-prompt-toast {
  position: fixed;
  left: 50%;
  bottom: 24px;
  transform: translateX(-50%) translateY(20px);
  z-index: 999999;
  max-width: min(92vw, 420px);
  padding: 12px 16px;
  border-radius: 14px;
  background: rgba(10, 10, 14, 0.92);
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.35);
  color: rgba(255, 255, 255, 0.92);
  font-size: 0.82rem;
  line-height: 1.45;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.28s ease, transform 0.28s ease;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.dgs-ai-prompt-toast.active {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}


.dgs-footer-ai-top {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
